import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layer_norm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>
__global__ void partial_reduce_kernel(const float* __restrict__ x,
                                       double* __restrict__ sum_out,
                                       double* __restrict__ sqsum_out,
                                       int N, int chunks_per_row) {
    int batch = blockIdx.x / chunks_per_row;
    int chunk = blockIdx.x % chunks_per_row;
    const float* x_ptr = x + (size_t)batch * N;
    extern __shared__ double sdata[];
    double* swarp_sum = sdata;
    double* swarp_sqsum = sdata + (blockDim.x / 32);
    int N4 = N / 4;
    int chunk_size4 = (N4 + chunks_per_row - 1) / chunks_per_row;
    int start4 = chunk * chunk_size4;
    int end4 = min(start4 + chunk_size4, N4);
    const float4* x_ptr4 = reinterpret_cast<const float4*>(x_ptr);
    double sum = 0.0, sqsum = 0.0;
    for (int i = start4 + threadIdx.x; i < end4; i += blockDim.x) {
        float4 v4 = x_ptr4[i];
        double v0 = (double)v4.x;
        double v1 = (double)v4.y;
        double v2 = (double)v4.z;
        double v3 = (double)v4.w;
        sum += v0 + v1 + v2 + v3;
        sqsum += v0 * v0 + v1 * v1 + v2 * v2 + v3 * v3;
    }
    if (chunk == chunks_per_row - 1) {
        for (int i = N4 * 4 + threadIdx.x; i < N; i += blockDim.x) {
            double v = (double)x_ptr[i];
            sum += v;
            sqsum += v * v;
        }
    }
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sqsum += __shfl_down_sync(mask, sqsum, offset);
    }
    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;
    if (lane_id == 0) {
        swarp_sum[warp_id] = sum;
        swarp_sqsum[warp_id] = sqsum;
    }
    __syncthreads();
    int num_warps = blockDim.x / 32;
    if (warp_id == 0) {
        sum = (lane_id < num_warps) ? swarp_sum[lane_id] : 0.0;
        sqsum = (lane_id < num_warps) ? swarp_sqsum[lane_id] : 0.0;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
            sqsum += __shfl_down_sync(mask, sqsum, offset);
        }
        if (lane_id == 0) {
            atomicAdd(&sum_out[batch], sum);
            atomicAdd(&sqsum_out[batch], sqsum);
        }
    }
}
__global__ void compute_mean_invstd_kernel(const double* __restrict__ sum,
                                            const double* __restrict__ sqsum,
                                            float* __restrict__ mean_out,
                                            float* __restrict__ invstd_out,
                                            int N, int batch_size, float eps) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        double s = sum[idx];
        double sq = sqsum[idx];
        double d_mean = s / N;
        double d_var = sq / N - d_mean * d_mean;
        mean_out[idx] = (float)d_mean;
        invstd_out[idx] = (float)rsqrt(d_var + (double)eps);
    }
}
__global__ void normalize_kernel(const float* __restrict__ x,
                                  const float* __restrict__ weight,
                                  const float* __restrict__ bias,
                                  float* __restrict__ out,
                                  const float* __restrict__ mean_arr,
                                  const float* __restrict__ invstd_arr,
                                  int N, int chunks_per_row) {
    int batch = blockIdx.x / chunks_per_row;
    int chunk = blockIdx.x % chunks_per_row;
    const float* x_ptr = x + (size_t)batch * N;
    float* out_ptr = out + (size_t)batch * N;
    float mean = mean_arr[batch];
    float inv_std = invstd_arr[batch];
    int N4 = N / 4;
    int chunk_size4 = (N4 + chunks_per_row - 1) / chunks_per_row;
    int start4 = chunk * chunk_size4;
    int end4 = min(start4 + chunk_size4, N4);
    const float4* x_ptr4 = reinterpret_cast<const float4*>(x_ptr);
    const float4* w_ptr4 = reinterpret_cast<const float4*>(weight);
    const float4* b_ptr4 = reinterpret_cast<const float4*>(bias);
    float4* out_ptr4 = reinterpret_cast<float4*>(out_ptr);
    for (int i = start4 + threadIdx.x; i < end4; i += blockDim.x) {
        float4 v4 = x_ptr4[i];
        float4 w4 = w_ptr4[i];
        float4 b4 = b_ptr4[i];
        float4 r;
        r.x = (v4.x - mean) * inv_std * w4.x + b4.x;
        r.y = (v4.y - mean) * inv_std * w4.y + b4.y;
        r.z = (v4.z - mean) * inv_std * w4.z + b4.z;
        r.w = (v4.w - mean) * inv_std * w4.w + b4.w;
        out_ptr4[i] = r;
    }
    if (chunk == chunks_per_row - 1) {
        for (int i = N4 * 4 + threadIdx.x; i < N; i += blockDim.x) {
            float v = x_ptr[i];
            out_ptr[i] = (v - mean) * inv_std * weight[i] + bias[i];
        }
    }
}
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);
    int64_t norm_numel = weight.numel();
    int64_t total = x_contig.numel();
    int64_t batch_size = total / norm_numel;
    auto options_double = torch::TensorOptions().dtype(torch::kFloat64).device(x.device());
    auto sum_tensor = torch::zeros({batch_size}, options_double);
    auto sqsum_tensor = torch::zeros({batch_size}, options_double);
    auto mean_tensor = torch::empty({batch_size}, x_contig.options());
    auto invstd_tensor = torch::empty({batch_size}, x_contig.options());
    const int threads = 256;
    int chunks_per_row = 64;
    // Avoid excessive chunking for small norm_numel
    int max_chunks = (int)std::max<int64_t>(1, norm_numel / (threads * 4));
    if (chunks_per_row > max_chunks) chunks_per_row = std::max(1, max_chunks);
    const int blocks = (int)batch_size * chunks_per_row;
    size_t shared_mem = 2 * (threads / 32) * sizeof(double);
    partial_reduce_kernel<<<blocks, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        sum_tensor.data_ptr<double>(),
        sqsum_tensor.data_ptr<double>(),
        (int)norm_numel,
        chunks_per_row
    );
    int mm_threads = 32;
    int mm_blocks = (int)((batch_size + mm_threads - 1) / mm_threads);
    compute_mean_invstd_kernel<<<mm_blocks, mm_threads>>>(
        sum_tensor.data_ptr<double>(),
        sqsum_tensor.data_ptr<double>(),
        mean_tensor.data_ptr<float>(),
        invstd_tensor.data_ptr<float>(),
        (int)norm_numel,
        (int)batch_size,
        (float)eps
    );
    normalize_kernel<<<blocks, threads>>>(
        x_contig.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        mean_tensor.data_ptr<float>(),
        invstd_tensor.data_ptr<float>(),
        (int)norm_numel,
        chunks_per_row
    );
    return out;
}
"""

layer_norm_cpp_source = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

layer_norm_module = load_inline(
    name="layer_norm_module",
    cpp_sources=layer_norm_cpp_source,
    cuda_sources=layer_norm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.layer_norm_op = layer_norm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.contiguous()
        bias = self.bias.contiguous()
        return self.layer_norm_op.layer_norm_cuda(x, weight, bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256

def get_inputs():
    x = torch.randn(batch_size, features, dim1, dim2)
    mean = 1000
    std_dev = 0.1
    x = x * std_dev + mean
    return [x]

def get_init_inputs():
    return [(features, dim1, dim2)]

